/* ==========================================================================
     CLAYMORPHISM DESIGN LANGUAGE — INFLATED 3D SURFACES & TACTILE CLAY
     ========================================================================== */

  

  /* --------------------------------------------------------------------------
     1. FOUNDATION & SCOPED VARIABLES
     -------------------------------------------------------------------------- */
  .lab-styled-preview[data-style="claymorphism"],
  .claymorphism-styled-container,
  .style-claymorphism {
    /* Foundation clay palette */
    --clay-bg: #f6f3eb;                  /* Warm soft cream clay ground */
    --clay-surface: #ffffff;             /* Crisp warm white clay slab */
    --clay-surface-subtle: #f8fafc;
    --clay-surface-recessed: #eeebdf;    /* Softly indented clay tray */
    
    /* Friendly controlled pastel clay accents */
    --clay-lavender: #ede9fe;
    --clay-lavender-text: #5b21b6;
    --clay-blue: #dbeafe;
    --clay-blue-text: #1e40af;
    --clay-mint: #d1fae5;
    --clay-mint-text: #065f46;
    --clay-peach: #ffedd5;
    --clay-peach-text: #9a3412;
    --clay-yellow: #fef9c3;
    --clay-yellow-text: #854d0e;
    --clay-coral: #ffe4e6;
    --clay-coral-text: #9f1239;

    /* Primary interactive tactile clay */
    --clay-primary: #6366f1;             /* Tactile indigo clay pill */
    --clay-primary-hover: #4f46e5;
    --clay-primary-active: #4338ca;
    --clay-primary-text: #ffffff;

    /* High-contrast accessible typography */
    --clay-text: #1e293b;                /* Slate charcoal (>12:1 on cream/white) */
    --clay-text-secondary: #475569;      /* Slate body gray (>6:1 contrast) */
    --clay-text-muted: #64748b;          /* Soft metadata slate */

    /* Inflated 3D clay depth tokens */
    --clay-card-shadow:
      inset 4px 5px 10px rgba(255, 255, 255, 0.95),
      inset -5px -6px 14px rgba(70, 60, 90, 0.07),
      12px 18px 36px -6px rgba(45, 35, 60, 0.08),
      4px 6px 14px -2px rgba(45, 35, 60, 0.04);

    --clay-card-shadow-hover:
      inset 4px 5px 10px rgba(255, 255, 255, 1),
      inset -5px -6px 14px rgba(70, 60, 90, 0.08),
      16px 24px 44px -6px rgba(45, 35, 60, 0.11),
      6px 8px 16px -2px rgba(45, 35, 60, 0.05);

    --clay-btn-shadow:
      inset 3px 3px 6px rgba(255, 255, 255, 0.45),
      inset -3px -4px 8px rgba(0, 0, 0, 0.22),
      0 10px 22px -4px rgba(99, 102, 241, 0.4),
      0 4px 8px -2px rgba(99, 102, 241, 0.2);

    --clay-btn-shadow-hover:
      inset 3px 3px 6px rgba(255, 255, 255, 0.55),
      inset -3px -4px 8px rgba(0, 0, 0, 0.22),
      0 14px 28px -4px rgba(99, 102, 241, 0.45),
      0 6px 10px -2px rgba(99, 102, 241, 0.25);

    --clay-btn-shadow-active:
